<script setup lang="ts">
import PmsTableControls from './PmsTableControls.vue';
import PmsDashboardChart from './PmsDashboardChart.vue';
import {ref,onMounted,computed} from 'vue';import {pmsApi} from './api';defineProps<{name?:string}>();const today=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date());const cardIcons:Record<string,string>={adminCount:'shield-lock',managerCount:'user',teamLeadCount:'users',employeeCount:'users',teamMembersCount:'users',teamLeadersCount:'users',projectCount:'folders',ongoingProjectCount:'list-check',completedProjectCount:'circle-check',cancelledProjectCount:'circle-x',totalTasksCount:'clipboard-list',pendingTasksCount:'clock',inProgressTasksCount:'loader',unassignedTasksCount:'user',completedTasksCount:'checks'};const portfolio=ref<any[]>([]),tablePage=ref(1),tableSize=ref(10),search=ref('');const teamTable=computed(()=>portfolio.value.length>0&&'assigned_tasks' in portfolio.value[0]);const shown=computed(()=>portfolio.value.filter(p=>String(p.name).toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));function projectPeople(p:any,leaders:boolean){return (p.users||[]).filter((u:any)=>u.roles?.some((role:any)=>['admin','project_manager','team_leader'].includes(role.role_key))===leaders);}const solidIcons:Record<string,string>={adminCount:'shield',managerCount:'tie',teamLeadCount:'team',employeeCount:'users',teamMembersCount:'users',teamLeadersCount:'team',ongoingProjectCount:'tasks',completedProjectCount:'check',cancelledProjectCount:'cancel'};const data=ref<any>(null),error=ref('');const labels:any={adminCount:'Admin',managerCount:'Project Manager',teamLeadCount:'Team Leader',employeeCount:'Employee',teamMembersCount:'Team Members',teamLeadersCount:'Team Leaders',projectCount:'Projects',ongoingProjectCount:'Ongoing Projects',completedProjectCount:'Completed Projects',cancelledProjectCount:'Cancelled Projects',totalTasksCount:'Total Tasks',pendingTasksCount:'Pending Tasks',inProgressTasksCount:'In Progress Tasks',unassignedTasksCount:'Unassigned Tasks',completedTasksCount:'Completed Tasks'};const cardColors:Record<string,string>={adminCount:'primary',managerCount:'success',teamLeadCount:'warning',employeeCount:'secondary',teamMembersCount:'secondary',teamLeadersCount:'warning',ongoingProjectCount:'primary',completedProjectCount:'success',cancelledProjectCount:'secondary'};const cards=computed(()=>Object.entries(labels).filter(([k])=>data.value?.[k]!=null));onMounted(async()=>{try{const [summary,table]=await Promise.all([pmsApi('dashboard'),pmsApi('dashboard/table')]);data.value=summary.data;portfolio.value=table.data;}catch(e){error.value=(e as Error).message;}});
</script><template><section class="dashboard-heading mb-4"><div><span class="dashboard-eyebrow">{{today}}</span><h2 class="dashboard-title">Welcome back, {{name||'Super Admin'}}</h2><p class="dashboard-subtitle mb-0">Here is what is happening across your workspace today.</p></div><div class="dashboard-actions"><a class="button" href="/pms?section=my-work"><i aria-hidden="true" class="ti ti-layout-kanban"></i>My work</a><a class="button primary" href="/pms?section=projects"><i aria-hidden="true" class="ti ti-folder"></i>View projects</a></div></section><p v-if="error" class="notice admin-error">{{error}}</p><p v-if="!data&&!error" role="status">Loading dashboard...</p><div class="row g-4 pms-dashboard-stats"><div v-for="[key,label] in cards" :key="key" class="col-xl-2 col-sm-6"><div class="card h-100 main-card show pms-dashboard-stat" :class="'stat-'+(String(key)==='completedProjectCount'?'secondary':cardColors[String(key)]||'primary')"><i aria-hidden="true" class="card-icon" :class="[solidIcons[String(key)]?'pms-fa pms-fa-'+solidIcons[String(key)]:'ti ti-'+cardIcons[String(key)],'text-'+(String(key)==='cancelledProjectCount'?'danger':cardColors[String(key)]||'primary')]"></i><h5 class="card-title">{{label}}</h5><h4>{{data[key]}}</h4></div></div></div><div v-if="data" class="row g-4 mt-1 dashboard-chart-grid"><div v-for="(chart,key) in data.dashboardCharts" :key="key" :class="String(key)==='projects'?'col-xl-5':'col-xl-7'"><div class="card h-100 dashboard-chart-card"><div class="card-body"><div class="d-flex justify-content-between align-items-start mb-2"><div><span class="dashboard-chart-kicker">{{String(key)==='projects'?'Portfolio':'Delivery flow'}}</span><h5 class="mb-1">{{String(key)==='projects'?'Project health':'Tasks by stage'}}</h5><p class="text-muted small mb-0">{{String(key)==='projects'?'Projects grouped by their current status':'Current workload across the delivery pipeline'}}</p></div><span class="dashboard-chart-icon"><i aria-hidden="true" class="ti" :class="String(key)==='projects'?'ti-chart-donut-3':'ti-chart-bar'"></i></span></div><PmsDashboardChart :kind="String(key)" :data="chart"/></div></div></div><div v-if="data.dashboardInsights?.show_workload" class="col-xl-7"><div class="card h-100 dashboard-chart-card"><div class="card-body"><div class="d-flex justify-content-between align-items-start mb-2"><div><span class="dashboard-chart-kicker">Team capacity</span><h5 class="mb-1">Workload by employee</h5><p class="text-muted small mb-0">Open tasks currently assigned to each person</p></div><span class="dashboard-chart-icon"><i aria-hidden="true" class="ti ti-users"></i></span></div><PmsDashboardChart kind="workload" :data="data.dashboardInsights.workload"/></div></div></div><div :class="data.dashboardInsights?.show_workload?'col-xl-5':'col-12'"><div class="card h-100 dashboard-deadline-card"><div class="card-body"><div class="d-flex justify-content-between align-items-start mb-3"><div><span class="dashboard-chart-kicker">Next 7 days</span><h5 class="mb-1">Upcoming deadlines</h5><p class="text-muted small mb-0">Tasks requiring attention soon</p></div><span class="dashboard-chart-icon"><i aria-hidden="true" class="ti ti-calendar"></i></span></div><article v-for="t in data.dashboardInsights?.deadlines" :key="t.id" class="pms-deadline-row"><a :href="'/pms?project='+t.project_id+'&issue='+t.id">{{t.title}}</a><small>{{t.project}}</small><span class="badge bg-label-warning">{{t.due_label}}</span></article><div v-if="!data.dashboardInsights?.deadlines.length" class="dashboard-insight-empty"><span><i aria-hidden="true" class="ti ti-calendar-check"></i></span><strong>No deadlines this week</strong><small>Your upcoming seven days are clear.</small></div></div></div></div></div><div v-if="data" class="card dashboard-table-card mt-4"><div class="card-body"><div class="dashboard-table-heading"><div><span class="dashboard-chart-kicker">Workspace</span><h5 class="mb-1">{{teamTable?'Team overview':'Project portfolio'}}</h5><p class="text-muted small mb-0">{{teamTable?'Assignment and delivery progress across your team.':'Delivery dates, ownership, team allocation, and completion progress.'}}</p></div><span class="dashboard-chart-icon"><i aria-hidden="true" class="ti ti-table"></i></span></div><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"/><div class="pms-table-scroll"><table class="pms-table"><thead><tr v-if="!teamTable"><th>Project</th><th>Durations</th><th>Leader</th><th>Team</th><th>Progress</th></tr><tr v-else><th>Name</th><th>Designation</th><th>Role</th><th>Projects</th><th>Tasks</th><th>Pending</th><th>In progress</th><th>Completed</th></tr></thead><tbody><tr v-for="(project,index) in paged" :key="project.id||index"><template v-if="!teamTable"><td><a :href="'/pms?project='+project.id" class="pms-portfolio-project"><img :src="project.image||'/pms-assets/assets/img/sm-logo.png'" class="dashboard-project-avatar" alt=""><strong>{{project.name}}</strong></a></td><td><span class="badge bg-primary">{{project.start_date||'Not set'}}</span> <span class="badge bg-warning">{{project.end_date||'No deadline'}}</span></td><td><div class="pms-portfolio-avatars"><span v-for="person in projectPeople(project,true)" :key="person.id" :title="person.name"><img v-if="person.profile_img" :src="person.profile_img" :alt="person.name"><span v-else>{{person.name.charAt(0)}}</span></span></div></td><td><div class="pms-portfolio-avatars"><span v-for="person in projectPeople(project,false)" :key="person.id" :title="person.name"><img v-if="person.profile_img" :src="person.profile_img" :alt="person.name"><span v-else>{{person.name.charAt(0)}}</span></span></div></td><td><div class="progress" style="height:8px;width:120px"><div class="progress-bar" :style="{width:project.completion_percentage+'%'}"></div></div><small>{{project.completion_percentage}}%</small></td></template><template v-else><td>{{project.name}}</td><td>{{project.designation}}</td><td>{{project.role}}</td><td>{{project.assigned_projects}}</td><td>{{project.assigned_tasks}}</td><td>{{project.pending_tasks}}</td><td>{{project.in_progress_tasks}}</td><td>{{project.completed_tasks}}</td></template></tr><tr v-if="!shown.length"><td :colspan="teamTable?8:5">No records found.</td></tr></tbody></table></div><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></div></template>